28	    uWind: { value: THREE.Vector3 };
29	    uMaskCol: { value: THREE.Color };
30	    uRoot: { value: THREE.Color };
31	    uTip: { value: THREE.Color };
32	    uClump: { value: number };
33	    uLock: { value: THREE.Vector4 };
