49	    uShort: { value: new THREE.Vector3(p.short?.[3] ?? 2, p.short?.[4] ?? 3, p.short?.[5] ?? 1) },
50	    uTime: { value: 0 },
51	    uWind: { value: new THREE.Vector3() },
52	    /** QA segmentation colour (only compiled in when material.defines.BENNY_MASK is set, see runtime.ts) */
53	    uMaskCol: { value: new THREE.Color(1, 0, 0) },
54	    /** `?benny05=1` only (material.defines.BENNY05, benny05.ts): strand clumping toward tuft centres */
55	    uClump: { value: 0.42 },
56	    /** `?benny20=1` only (material.defines.BENNY20, benny20.ts): soft plush LOCKS instead of single needles —
57	     *  x = lock cells per unit, y = lock base radius (cell units), z = vertical lock stretch (< 1: combed, elongated
58	     *  downward), w = fine strand cells per unit inside a lock */
59	    uLock: { value: new THREE.Vector4(8, 0.72, 0.62, 110) },
60	    /** `?benny20=1`: x = colour at the roots / in the creases (fraction), y = extra lightness at the lock tips,
