66	  const material = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.9, metalness: 0 });
67	  material.onBeforeCompile = (shader) => {
68	    Object.assign(shader.uniforms, uniforms);
69	    shader.vertexShader = shader.vertexShader
70	      .replace(
71	        '#include <common>',
72	        `#include <common>
73	        uniform float uFurLen; uniform float uGravity; uniform vec4 uBald;
74	        uniform vec3 uShortDir; uniform vec3 uShort; uniform float uTime; uniform vec3 uWind;
75	        varying float vLayer; varying vec3 vBase; varying float vLenMask;
76	        #ifdef BENNY05
